import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    records = list(reader)

    # Locate the header after any preamble, preferring the expected four-column
    # header shape. If none matches, fall back to the first nonblank record.
    header_index = None
    for i, row in enumerate(records):
        if row and len(row) == 4:
            header_index = i
            break

    if header_index is None:
        for i, row in enumerate(records):
            if row:
                header_index = i
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    data = records[header_index + 1:]
    width = max([len(columns)] + [len(row) for row in data])

    while len(columns) < width:
        columns.append(f"column_{len(columns) + 1}")

    rows = []
    for row in data:
        normalized = list(row[:width])
        normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
